    return attemptsReady && !game.started && game.moves === 0 && game.matched.length === 0;
  }
  if (phase === 'playing') {
    return (turn === 0 ? first === null && second === null : first !== null && second === null) && !isWon(game);
  }
  if (phase === 'between-turns') {
    return turn === 0 && first !== null && second === null && isWon(game) && sameResult(first, game);
  }
  if (phase === 'between-matches') {
    return (
      turn === 1 &&
      first !== null &&
      second !== null &&
      activeIndex < matches.length - 1 &&
      isWon(game) &&
      sameResult(second, game)
    );
  }
  return (
    phase === 'finished' &&
    turn === 1 &&
    first !== null &&
    second !== null &&
    activeIndex === matches.length - 1 &&
    isWon(game) &&
    sameResult(second, game)
  );
}

function sameResult(result: NonNullable<TournamentState['matches'][number]['results'][number]>, game: GameState) {
  return result.moves === game.moves && Math.floor(result.elapsedMs) === game.elapsedMs;
}

function isTournamentPhase(value: unknown): value is TournamentState['phase'] {
  return (
    value === 'ready' ||
    value === 'playing' ||
    value === 'between-turns' ||
    value === 'between-matches' ||
    value === 'finished'
  );
}

