import type { TournamentPlayerCount, TournamentRound, TournamentResult } from './types.ts';

export interface MatchPlan {
  readonly id: string;
  readonly number: number;
  readonly round: TournamentRound;
  readonly size: 4 | 6 | 8;
  readonly openingPlayers: readonly [number | null, number | null];
  readonly sources: readonly [number | null, number | null];
}

export type NameValidation =
  | { readonly ok: true; readonly names: readonly string[] }
  | { readonly ok: false; readonly error: string };

export const TournamentNameError = {
  length: 'Use 2 to 20 characters.',
  duplicate: 'Each name must be different.',
} as const;

export function normalizePlayerNames(
  drafts: readonly string[],
  playerCount: TournamentPlayerCount,
): NameValidation {
  const names = Array.from({ length: playerCount }, (_, index) =>
    (drafts[index] ?? '').trim().replace(/\s+/gu, ' ').normalize('NFC'),
  );
  if (names.some((name) => Array.from(name).length < 2 || Array.from(name).length > 20)) {
    return { ok: false, error: TournamentNameError.length };
  }
  const comparisonNames = names.map((name) => name.toLowerCase());
  if (new Set(comparisonNames).size !== names.length) {
    return { ok: false, error: TournamentNameError.duplicate };
  }
  return { ok: true, names };
}

export function tournamentMatchPlans(playerCount: TournamentPlayerCount): readonly MatchPlan[] {
  if (playerCount === 4) {
    return [
      {
        id: 'S1',
        number: 1,
        round: 'Semifinal',
        size: 6,
        openingPlayers: [1, 4],
        sources: [null, null],
      },
      {
        id: 'S2',
        number: 2,
        round: 'Semifinal',
        size: 6,
        openingPlayers: [2, 3],
        sources: [null, null],
      },
      {
        id: 'F1',
        number: 1,
        round: 'Final',
        size: 8,
        openingPlayers: [null, null],
        sources: [0, 1],
      },
    ];
  }
  return [
    { id: 'Q1', number: 1, round: 'Quarterfinal', size: 4, openingPlayers: [1, 8], sources: [null, null] },
    { id: 'Q2', number: 2, round: 'Quarterfinal', size: 4, openingPlayers: [4, 5], sources: [null, null] },
    { id: 'Q3', number: 3, round: 'Quarterfinal', size: 4, openingPlayers: [3, 6], sources: [null, null] },
    { id: 'Q4', number: 4, round: 'Quarterfinal', size: 4, openingPlayers: [2, 7], sources: [null, null] },
    { id: 'S1', number: 1, round: 'Semifinal', size: 6, openingPlayers: [null, null], sources: [0, 1] },
    { id: 'S2', number: 2, round: 'Semifinal', size: 6, openingPlayers: [null, null], sources: [2, 3] },
    { id: 'F1', number: 1, round: 'Final', size: 8, openingPlayers: [null, null], sources: [4, 5] },
  ];
}

// A lower move count wins, then a lower active time, then the higher seed (seed 1).
export function winningSeed(
  seeds: readonly [number, number],
  results: readonly [TournamentResult, TournamentResult],
): number {
  if (results[0].moves !== results[1].moves) {
    return results[0].moves < results[1].moves ? seeds[0] : seeds[1];
  }
  if (results[0].elapsedMs !== results[1].elapsedMs) {
    return results[0].elapsedMs < results[1].elapsedMs ? seeds[0] : seeds[1];
  }
  return Math.min(seeds[0], seeds[1]);
}
import type { GameState } from '../game.ts';

export type TournamentPlayerCount = 4 | 8;
export const TOURNAMENT_FORMAT = 'neon-pairs/tournament';
export const TOURNAMENT_FORMAT_VERSION = 1;
export type TournamentRound = 'Quarterfinal' | 'Semifinal' | 'Final';
export type TournamentPhase =
  | 'ready'
  | 'playing'
  | 'between-turns'
  | 'between-matches'
  | 'finished';

export interface TournamentPlayer {
  readonly name: string;
  readonly seed: number;
}

export interface TournamentResult {
  readonly moves: number;
  readonly elapsedMs: number;
}

export interface TournamentMatch {
  readonly id: string;
  readonly number: number;
  readonly round: TournamentRound;
  readonly size: number;
  readonly boardCode: string;
  readonly players: readonly [number | null, number | null];
  readonly results: readonly [TournamentResult | null, TournamentResult | null];
  readonly winnerSeed: number | null;
}

export interface TournamentState {
  readonly playerCount: TournamentPlayerCount;
  readonly players: readonly TournamentPlayer[];
  readonly matches: readonly TournamentMatch[];
  readonly activeMatch: number;
  readonly turnIndex: 0 | 1;
  readonly phase: TournamentPhase;
  readonly game: GameState;
}

export interface PastTournament {
  readonly playerCount: TournamentPlayerCount;
  readonly players: readonly TournamentPlayer[];
  readonly matches: readonly TournamentMatch[];
  readonly championSeed: number;
}

export interface TournamentSetup {
  readonly playerCount: TournamentPlayerCount;
  readonly names: readonly string[];
}

export type TournamentImport =
  | { readonly kind: 'setup'; readonly setup: TournamentSetup }
  | { readonly kind: 'tournament'; readonly tournament: TournamentState };
import { encodeSnapshot } from '../snapshot.ts';
import { isJsonObject, isWithinBytes, parseJson } from '../saved-format.ts';
import {
  TOURNAMENT_FORMAT,
  TOURNAMENT_FORMAT_VERSION,
} from './types.ts';
import { readTournamentSetup, readTournamentState } from './validation.ts';
import type { TournamentImport, TournamentSetup, TournamentState } from './types.ts';

export const TOURNAMENT_JSON_MAX_BYTES = 65_536;

export function encodeTournament(setup: TournamentSetup, tournament: TournamentState | null): string {
  if (!tournament) {
    return JSON.stringify(
      {
        format: TOURNAMENT_FORMAT,
        names: [...setup.names],
        playerCount: setup.playerCount,
        state: 'setup',
        version: TOURNAMENT_FORMAT_VERSION,
      },
      null,
      2,
    );
  }
  return JSON.stringify(
    {
      activeMatch: tournament.activeMatch,
      format: TOURNAMENT_FORMAT,
      game: encodeSnapshot(tournament.game),
      matches: tournament.matches.map((match) => ({
        boardCode: match.boardCode,
        id: match.id,
        number: match.number,
        players: [...match.players],
        results: match.results.map((result) =>
          result ? { elapsedMs: result.elapsedMs, moves: result.moves } : null,
        ),
        round: match.round,
        size: match.size,
        winnerSeed: match.winnerSeed,
      })),
      phase: tournament.phase,
      playerCount: tournament.playerCount,
      players: tournament.players.map((player) => ({ name: player.name, seed: player.seed })),
      state: 'tournament',
      turnIndex: tournament.turnIndex,
      version: TOURNAMENT_FORMAT_VERSION,
    },
    null,
    2,
  );
}

export function decodeTournament(text: string): TournamentImport | null {
  const value = isWithinBytes(text, TOURNAMENT_JSON_MAX_BYTES) ? parseJson(text) : undefined;
  if (!isJsonObject(value) || value.format !== TOURNAMENT_FORMAT) return null;
  if (value.state === 'setup') {
    const setup = readTournamentSetup(value);
    return setup ? { kind: 'setup', setup } : null;
  }
  if (value.state === 'tournament') {
    const tournament = readTournamentState(value);
    return tournament ? { kind: 'tournament', tournament } : null;
  }
  return null;
}

import { TOURNAMENT_JSON_MAX_BYTES } from './format.ts';

interface TournamentExchangeProps {
  readonly value: string;
  onChange(value: string): void;
  onExport(): string;
  onLoad(value: string): void;
}

export function TournamentExchange({ value, onChange, onExport, onLoad }: TournamentExchangeProps) {
  function exportTournament(): void {
    onChange(onExport());
  }
  return (
    <section className="tournament-exchange" aria-labelledby="tournament-exchange-heading">
      <h3 id="tournament-exchange-heading">Share a tournament</h3>
      <label htmlFor="tournament-json">Tournament JSON</label>
      <textarea
        id="tournament-json"
        className="control"
        rows={8}
        maxLength={TOURNAMENT_JSON_MAX_BYTES}
        spellCheck={false}
        value={value}
        onChange={(event) => onChange(event.currentTarget.value)}
      />
      <div className="tournament-actions">
        <button type="button" className="control" onClick={exportTournament}>
          Export tournament
        </button>
        <button type="button" className="control" onClick={() => onLoad(value)}>
          Load tournament
        </button>
      </div>
    </section>
  );
}
