export function decodeTournament(text: string): TournamentImport | null {
  const value = isWithinBytes(text, TOURNAMENT_JSON_MAX_BYTES) ? parseJson(text) : undefined;
  if (!isJsonObject(value) || value.format !== TOURNAMENT_FORMAT) return null;
  if (value.state === 'setup') {
    const setup = readTournamentSetup(value);
    return setup ? { kind: 'setup', setup } : null;
  }
  if (value.state === 'tournament') {
    const tournament = readTournamentState(value);
    return tournament ? { kind: 'tournament', tournament } : null;
  }
  return null;
}

