  return names ? { playerCount: value.playerCount, names } : null;
}

export function readTournamentState(value: unknown): TournamentState | null {
  if (
    !isJsonObject(value) ||
    !hasExactKeys(value, EVENT_KEYS) ||
    value.format !== TOURNAMENT_FORMAT ||
    value.version !== TOURNAMENT_FORMAT_VERSION ||
    value.state !== 'tournament' ||
    !isPlayerCount(value.playerCount) ||
    !isNonnegativeSafeInteger(value.activeMatch) ||
    (value.turnIndex !== 0 && value.turnIndex !== 1) ||
    !isTournamentPhase(value.phase) ||
    !isJsonObject(value.game)
  )
    return null;
  const players = readTournamentPlayers(value.players, value.playerCount);
  const matches = readTournamentMatches(value.matches, value.playerCount);
  const gameText = JSON.stringify(value.game);
  if (!gameText) return null;
  const game = decodeSnapshot(gameText);
  if (!players || !matches || !game || value.activeMatch >= matches.length) return null;
  const active = matches[value.activeMatch];
  if (!active || active.players[0] === null || active.players[1] === null) return null;
  if (game.boardCode !== active.boardCode || game.size !== active.size) return null;
  if (!validMatchProgress(matches, value.activeMatch)) return null;
  if (!validCurrentTurn(value.phase, value.turnIndex, value.activeMatch, matches, game))
    return null;
  return {
    playerCount: value.playerCount,
    players,
    matches,
    activeMatch: value.activeMatch,
    turnIndex: value.turnIndex,
    phase: value.phase,
    game,
  };
}

export function readPastTournament(value: unknown): PastTournament | null {
  if (!isJsonObject(value) || !hasExactKeys(value, PAST_KEYS) || !isPlayerCount(value.playerCount))
    return null;
  const players = readTournamentPlayers(value.players, value.playerCount);
  const matches = readTournamentMatches(value.matches, value.playerCount);
  if (!players || !matches || !isNonnegativeSafeInteger(value.championSeed)) return null;
  if (matches.some((match) => match.winnerSeed === null)) return null;
  const final = matches[matches.length - 1];
  if (!final || final.winnerSeed !== value.championSeed) return null;
  return { playerCount: value.playerCount, players, matches, championSeed: value.championSeed };
}

function readDraftNames(value: unknown): string[] | null {
  if (!Array.isArray(value) || value.length !== 8) return null;
  const names: string[] = [];
  for (let index = 0; index < value.length; index += 1) {
    const name: unknown = value[index];
    if (typeof name !== 'string' || Array.from(name).length > 256) return null;
    names.push(name);
  }
  return names;
}

function validMatchProgress(
  matches: TournamentState['matches'],
  activeIndex: number,
): boolean {
  return matches.every((match, index) => {
    if (index < activeIndex) return match.winnerSeed !== null;
    if (index > activeIndex) {
      return (
        match.winnerSeed === null &&
        match.results[0] === null &&
        match.results[1] === null
      );
    }
    return true;
  });
}

function validCurrentTurn(
  phase: TournamentState['phase'],
  turn: TournamentState['turnIndex'],
  activeIndex: number,
  matches: TournamentState['matches'],
  game: GameState,
): boolean {
  const match = matches[activeIndex];
  if (!match) return false;
  const [first, second] = match.results;
  if (phase === 'ready') {
    const attemptsReady =
      turn === 0 ? first === null && second === null : first !== null && second === null;
    return attemptsReady && !game.started && game.moves === 0 && game.matched.length === 0;
  }
  if (phase === 'playing') {
    const attemptsReady =
      turn === 0 ? first === null && second === null : first !== null && second === null;
    return attemptsReady && !isWon(game);
  }
  if (phase === 'between-turns') {
    return (
      turn === 0 &&
      first !== null &&
      second === null &&
      isWon(game) &&
      sameResult(first, game)
    );
  }
  if (phase === 'between-matches') {
    return (
      turn === 1 &&
      first !== null &&
      second !== null &&
      activeIndex < matches.length - 1 &&
      isWon(game) &&
      sameResult(second, game)
    );
  }
  return (
    phase === 'finished' &&
    turn === 1 &&
    first !== null &&
    second !== null &&
    activeIndex === matches.length - 1 &&
    isWon(game) &&
    sameResult(second, game)
  );
}

function sameResult(
  result: NonNullable<TournamentState['matches'][number]['results'][number]>,
  game: GameState,
) {
  return result.moves === game.moves && Math.floor(result.elapsedMs) === game.elapsedMs;
}

function isTournamentPhase(value: unknown): value is TournamentState['phase'] {
  return (
    value === 'ready' ||
    value === 'playing' ||
    value === 'between-turns' ||
    value === 'between-matches' ||
    value === 'finished'
  );
}

import { useEffect, useRef } from 'react';
import { Board } from '../board/Board.tsx';
import type { BoardFocus } from '../board/Board.tsx';
import { StatusLabel } from '../status/status-labels.ts';
import { formatElapsed } from '../elapsed-time.ts';
import { TournamentLeaveDialog } from './TournamentLeaveDialog.tsx';
import type { TournamentState } from './types.ts';

interface TournamentPlayProps {
  readonly tournament: TournamentState;
  readonly statusNotice: string;
  readonly announcement: number;
  onStartTurn(): void;
  onNextTurn(): void;
  onNextMatch(): void;
  onLeave(): void;
  onBackToGame(): void;
  onActivate(index: number): void;
}

export function TournamentPlay({
  tournament,
  statusNotice,
  announcement,
  onStartTurn,
  onNextTurn,
  onNextMatch,
  onLeave,
  onBackToGame,
  onActivate,
}: TournamentPlayProps) {
  const board = useRef<BoardFocus>(null);
  const actionButton = useRef<HTMLButtonElement>(null);
  const previousPhase = useRef(tournament.phase);
  const match = tournament.matches[tournament.activeMatch];
  const seed = match?.players[tournament.turnIndex];
  const player = tournament.players.find((candidate) => candidate.seed === seed);
  const name = player?.name ?? 'Player';
  const final = tournament.matches[tournament.matches.length - 1];
  const champion = tournament.players.find((candidate) => candidate.seed === final?.winnerSeed);

  useEffect(() => {
    if (tournament.phase === 'ready' && !statusNotice) {
      actionButton.current?.focus();
    } else if (previousPhase.current === 'ready' && tournament.phase === 'playing') {
      board.current?.focusRemembered();
    } else if (previousPhase.current === 'playing' && tournament.phase !== 'playing') {
      actionButton.current?.focus();
    }
    previousPhase.current = tournament.phase;
  }, [tournament.phase, statusNotice]);

  if (!match) return null;
  const action =
    tournament.phase === 'ready'
      ? { label: 'Start turn', run: onStartTurn }
      : tournament.phase === 'between-turns'
        ? { label: 'Next turn', run: onNextTurn }
        : tournament.phase === 'between-matches'
          ? { label: 'Next match', run: onNextMatch }
          : tournament.phase === 'finished'
            ? { label: 'Back to game', run: onBackToGame }
            : null;
  const matchWinner = match.winnerSeed
    ? tournament.players.find((candidate) => candidate.seed === match.winnerSeed)
    : undefined;
  const showBoard = tournament.phase === 'playing';
  const statusKind =
    tournament.phase === 'ready'
      ? 'ready'
      : tournament.phase === 'playing'
        ? 'playing'
        : tournament.phase === 'between-turns'
          ? 'turn-complete'
          : tournament.phase === 'between-matches'
            ? 'match-complete'
            : 'champion';
  const phaseText =
    statusKind === 'ready'
      ? `Ready for: ${name}`
      : statusKind === 'playing'
        ? `Now playing: ${name}`
        : statusKind === 'turn-complete'
          ? `Turn complete: ${name}`
          : statusKind === 'match-complete'
            ? `Match winner: ${matchWinner?.name ?? 'Unknown'}`
            : `Champion: ${champion?.name ?? 'Unknown'}`;
  const statusText = statusNotice ? `${statusNotice} ${phaseText}` : phaseText;
  const statusKey = statusNotice
    ? `notice-${announcement}`
    : `${tournament.activeMatch}-${tournament.turnIndex}-${statusKind}`;

  return (
    <section className="tournament-play" aria-labelledby="tournament-play-heading">
      <h3 id="tournament-play-heading">Current match</h3>
      <p>Round: {match.round}</p>
      <div className="tournament-status">
        <p
          role="status"
          aria-live="polite"
          aria-atomic="true"
          className={tournament.phase === 'finished' && !statusNotice ? 'tournament-champion' : ''}
        >
          <span key={statusKey}>{statusText}</span>
        </p>
      </div>
      <p className="tournament-deal-code">Deal: {match.boardCode}</p>
      <div className="tournament-stats" aria-label="Current game results">
        <dl>
          <div>
            <dt>{StatusLabel.moves}</dt>
            <dd>{tournament.game.moves}</dd>
          </div>
          <div>
            <dt>{StatusLabel.pairs}</dt>
            <dd>
              {tournament.game.matched.length / 2}/{tournament.game.deck.length / 2}
            </dd>
          </div>
          <div>
            <dt>{StatusLabel.time}</dt>
            <dd>{formatElapsed(tournament.game.elapsedMs)}</dd>
          </div>
        </dl>
      </div>
      <div className="tournament-actions">
        {action && (
          <button ref={actionButton} type="button" className="control" onClick={action.run}>
            {action.label}
          </button>
        )}
        <TournamentLeaveDialog visible={tournament.phase !== 'finished'} onLeave={onLeave} />
      </div>
      {showBoard && (
        <>
          <p id="board-help" className="help">
            Use a pointer or Tab to enter the board. Arrow keys move between cards. Enter or Space
            reveals a card.
          </p>
          <Board
            key={`${match.id}-${tournament.turnIndex}`}
            game={tournament.game}
            activate={onActivate}
            ref={board}
          />
        </>
      )}
    </section>
  );
}
import { useEffect, useRef, useState } from 'react';

interface TournamentLeaveDialogProps {
  readonly visible: boolean;
  onLeave(): void;
}

export function TournamentLeaveDialog({ visible, onLeave }: TournamentLeaveDialogProps) {
  const dialog = useRef<HTMLDialogElement>(null);
  const keepPlaying = useRef<HTMLButtonElement>(null);
  const [open, setOpen] = useState(false);

  useEffect(() => {
    if (open) {
      dialog.current?.showModal();
      keepPlaying.current?.focus();
    }
  }, [open]);

  function continueTournament(): void {
    dialog.current?.close();
    setOpen(false);
  }

  function leaveTournament(): void {
    dialog.current?.close();
    setOpen(false);
    onLeave();
  }

  return (
    <>
      {visible && (
        <button type="button" className="control" onClick={() => setOpen(true)}>
          Leave tournament
        </button>
      )}
      <dialog
        ref={dialog}
        className="tournament-confirm"
        aria-labelledby="leave-tournament-heading"
        onCancel={() => setOpen(false)}
      >
        <h2 id="leave-tournament-heading">Leave tournament?</h2>
        <p>The current tournament will stop.</p>
        <div className="tournament-actions">
          <button
            ref={keepPlaying}
            type="button"
            className="control"
            onClick={continueTournament}
          >
            Keep playing
          </button>
          <button type="button" className="control" onClick={leaveTournament}>
            Leave
          </button>
        </div>
      </dialog>
    </>
  );
}

