import type { TournamentPlayerCount, TournamentRound, TournamentResult } from './types.ts';

export interface MatchPlan {
  readonly id: string;
  readonly number: number;
  readonly round: TournamentRound;
  readonly size: 4 | 6 | 8;
  readonly openingPlayers: readonly [number | null, number | null];
  readonly sources: readonly [number | null, number | null];
}

export type NameValidation =
  | { readonly ok: true; readonly names: readonly string[] }
  | { readonly ok: false; readonly error: string };

export const TournamentNameError = {
  length: 'Use 2 to 20 characters.',
  duplicate: 'Each name must be different.',
} as const;

export function normalizePlayerNames(
  drafts: readonly string[],
  playerCount: TournamentPlayerCount,
): NameValidation {
  const names = Array.from({ length: playerCount }, (_, index) =>
    (drafts[index] ?? '').trim().replace(/\s+/gu, ' ').normalize('NFC'),
  );
  if (names.some((name) => Array.from(name).length < 2 || Array.from(name).length > 20)) {
    return { ok: false, error: TournamentNameError.length };
  }
  const comparisonNames = names.map((name) => name.toLowerCase());
  if (new Set(comparisonNames).size !== names.length) {
    return { ok: false, error: TournamentNameError.duplicate };
  }
  return { ok: true, names };
}

export function tournamentMatchPlans(playerCount: TournamentPlayerCount): readonly MatchPlan[] {
  if (playerCount === 4) {
    return [
      {
        id: 'S1',
        number: 1,
        round: 'Semifinal',
        size: 6,
        openingPlayers: [1, 4],
        sources: [null, null],
      },
      {
        id: 'S2',
        number: 2,
        round: 'Semifinal',
        size: 6,
        openingPlayers: [2, 3],
        sources: [null, null],
      },
      {
        id: 'F1',
        number: 1,
        round: 'Final',
        size: 8,
        openingPlayers: [null, null],
        sources: [0, 1],
      },
    ];
  }
  return [
    {
      id: 'Q1',
      number: 1,
      round: 'Quarterfinal',
      size: 4,
      openingPlayers: [1, 8],
      sources: [null, null],
    },
    {
      id: 'Q2',
      number: 2,
      round: 'Quarterfinal',
      size: 4,
      openingPlayers: [4, 5],
      sources: [null, null],
    },
    {
      id: 'Q3',
      number: 3,
      round: 'Quarterfinal',
      size: 4,
      openingPlayers: [3, 6],
      sources: [null, null],
    },
    {
      id: 'Q4',
      number: 4,
      round: 'Quarterfinal',
      size: 4,
      openingPlayers: [2, 7],
      sources: [null, null],
    },
    {
      id: 'S1',
      number: 1,
      round: 'Semifinal',
      size: 6,
      openingPlayers: [null, null],
      sources: [0, 1],
    },
    {
      id: 'S2',
      number: 2,
      round: 'Semifinal',
      size: 6,
      openingPlayers: [null, null],
      sources: [2, 3],
    },
    {
      id: 'F1',
      number: 1,
      round: 'Final',
      size: 8,
      openingPlayers: [null, null],
      sources: [4, 5],
    },
  ];
}

// A lower move count wins, then a lower active time, then the higher seed (seed 1).
export function winningSeed(
  seeds: readonly [number, number],
  results: readonly [TournamentResult, TournamentResult],
): number {
  if (results[0].moves !== results[1].moves) {
    return results[0].moves < results[1].moves ? seeds[0] : seeds[1];
  }
  if (results[0].elapsedMs !== results[1].elapsedMs) {
    return results[0].elapsedMs < results[1].elapsedMs ? seeds[0] : seeds[1];
  }
  return Math.min(seeds[0], seeds[1]);
}
import { ELAPSED_MAX_MS, MOVES_MAX } from '../game.ts';
import { parseBoardCode } from '../deck.ts';
import { hasExactKeys, isJsonObject, isNonnegativeSafeInteger } from '../saved-format.ts';
import { normalizePlayerNames, tournamentMatchPlans, winningSeed } from './rules.ts';
import type {
  TournamentMatch,
  TournamentPlayer,
  TournamentPlayerCount,
  TournamentResult,
} from './types.ts';

const PLAYER_KEYS = ['name', 'seed'] as const;
const MATCH_KEYS = [
  'boardCode',
  'id',
  'number',
  'players',
  'results',
  'round',
  'size',
  'winnerSeed',
] as const;
const RESULT_KEYS = ['elapsedMs', 'moves'] as const;

export function isPlayerCount(value: unknown): value is TournamentPlayerCount {
  return value === 4 || value === 8;
}

export function readTournamentPlayers(
  value: unknown,
  count: TournamentPlayerCount,
): TournamentPlayer[] | null {
  if (!Array.isArray(value) || value.length !== count) return null;
  const players: TournamentPlayer[] = [];
  for (let index = 0; index < value.length; index += 1) {
    const entry: unknown = value[index];
    if (!isJsonObject(entry) || !hasExactKeys(entry, PLAYER_KEYS)) return null;
    if (typeof entry.name !== 'string' || entry.seed !== index + 1) return null;
    players.push({ name: entry.name, seed: entry.seed });
  }
  const normalized = normalizePlayerNames(players.map((player) => player.name), count);
  return normalized.ok && normalized.names.every((name, index) => name === players[index]?.name)
    ? players
    : null;
}

export function readTournamentMatches(
  value: unknown,
  count: TournamentPlayerCount,
): TournamentMatch[] | null {
  const plans = tournamentMatchPlans(count);
  if (!Array.isArray(value) || value.length !== plans.length) return null;
  const matches: TournamentMatch[] = [];
  const codes = new Set<string>();
  for (let index = 0; index < value.length; index += 1) {
    const entry: unknown = value[index];
    const plan = plans[index];
    if (!plan || !isJsonObject(entry) || !hasExactKeys(entry, MATCH_KEYS)) return null;
    if (
      entry.id !== plan.id ||
      entry.number !== plan.number ||
      entry.round !== plan.round ||
      entry.size !== plan.size ||
      typeof entry.boardCode !== 'string'
    )
      return null;
    const parsed = parseBoardCode(entry.boardCode);
    const players = readNullablePair(entry.players, (seed) => isSeed(seed, count));
    const results = readNullablePair(entry.results, (result) =>
      isTournamentResult(result, plan.size),
    );
    const winnerSeed = entry.winnerSeed;
    if (!parsed || parsed.size !== plan.size || codes.has(entry.boardCode) || !players || !results)
      return null;
    if (winnerSeed !== null && !isSeed(winnerSeed, count)) return null;
    codes.add(entry.boardCode);
    matches.push({
      id: plan.id,
      number: plan.number,
      round: plan.round,
      size: plan.size,
      boardCode: entry.boardCode,
      players,
      results,
      winnerSeed,
    });
  }
  return validateMatchOutcomes(matches, plans, count) ? matches : null;
}

export function isSeed(value: unknown, count: TournamentPlayerCount): value is number {
  return isNonnegativeSafeInteger(value) && value >= 1 && value <= count;
}

function validateMatchOutcomes(
  matches: readonly TournamentMatch[],
  plans: ReturnType<typeof tournamentMatchPlans>,
  count: TournamentPlayerCount,
): boolean {
  for (let index = 0; index < matches.length; index += 1) {
    const match = matches[index];
    const plan = plans[index];
    if (!match || !plan) return false;
    for (const slot of [0, 1] as const) {
      const source = plan.sources[slot];
      const expected =
        source === null ? plan.openingPlayers[slot] : matches[source]?.winnerSeed ?? null;
      if (match.players[slot] !== expected) return false;
      if (match.players[slot] === null && match.results[slot] !== null) return false;
    }
    if (match.results[1] !== null && match.results[0] === null) return false;
    const [firstSeed, secondSeed] = match.players;
    const [firstResult, secondResult] = match.results;
    if (firstResult !== null && secondResult !== null) {
      if (firstSeed === null || secondSeed === null) return false;
      if (
        match.winnerSeed !== winningSeed([firstSeed, secondSeed], [firstResult, secondResult])
      )
        return false;
    } else if (match.winnerSeed !== null) {
      return false;
    }
  }
  return matches.every((match) =>
    match.players.every((seed) => seed === null || isSeed(seed, count)),
  );
}

function readNullablePair<T>(
  value: unknown,
  read: (item: unknown) => item is T,
): readonly [T | null, T | null] | null {
  if (!Array.isArray(value) || value.length !== 2) return null;
  const first: unknown = value[0];
  const second: unknown = value[1];
  if (first !== null && !read(first)) return null;
  if (second !== null && !read(second)) return null;
  return [first, second];
}

function isTournamentResult(value: unknown, size: number): value is TournamentResult {
  if (!isJsonObject(value) || !hasExactKeys(value, RESULT_KEYS)) return false;
  return (
    typeof value.moves === 'number' &&
    Number.isSafeInteger(value.moves) &&
    value.moves >= (size * size) / 2 &&
    value.moves <= MOVES_MAX &&
    typeof value.elapsedMs === 'number' &&
    Number.isFinite(value.elapsedMs) &&
    value.elapsedMs >= 0 &&
    value.elapsedMs <= ELAPSED_MAX_MS
  );
}

import { useRef, useState } from 'react';
import { createGame } from '../game.ts';
import { parseBoardCode, isValidSize } from '../deck.ts';
import { decodeSnapshot, encodeSnapshot } from '../snapshot.ts';
import { freshBoardCode } from './fresh-board.ts';
import { activateSession, initialSession, replaceGame, SessionNotice } from './session.ts';
import { readPreferences } from './storage.ts';
import { browserStore, useSavedPreferences } from './use-saved-preferences.ts';
import { useSessionClock } from './use-session-clock.ts';
import type { Session } from './session.ts';

export function useGame(active = true) {
  const [store] = useState(browserStore);
  const [session, setSession] = useState(() => {
    const preferences = readPreferences(store);
    return initialSession(freshBoardCode(preferences.size), preferences);
  });
  const current = useRef(session);

  function commit(next: Session): void {
    if (next === current.current) return;
    current.current = next;
    setSession(next);
  }

  const clock = useSessionClock(session, current, commit, active);
  useSavedPreferences(store, session.preferences);

  function newGame(size = current.current.game.size): void {
    if (!isValidSize(size)) return;
    const next = createGame(freshBoardCode(size, current.current.game.seed));
    clock.reset();
    commit(replaceGame(current.current, next, false));
  }

  function restart(): void {
    clock.reset();
    commit(replaceGame(current.current, createGame(current.current.game.boardCode), false));
  }

  function notice(feedback: string): void {
    commit({
      ...current.current,
      feedback,
      loadNotice: feedback,
      announcement: current.current.announcement + 1,
    });
  }

  function loadBoard(code: string): boolean {
    code = code.trim();
    if (!parseBoardCode(code)) {
      notice(SessionNotice.invalidBoard);
      return false;
    }
    clock.reset();
    commit(replaceGame(current.current, createGame(code), false));
    return true;
  }

  function loadSnapshot(text: string): boolean {
    const game = decodeSnapshot(text);
    if (!game) {
      notice(SessionNotice.invalidSnapshot);
      return false;
    }
    clock.reset();
    commit(replaceGame(current.current, game, true));
    return true;
  }

  function exportSnapshot(): string {
    // Rendered state can trail the active clock by a tick.
    clock.synchronize();
    return encodeSnapshot(current.current.game);
  }

  function activate(index: number): void {
    clock.synchronize();
    commit(activateSession(current.current, index));
  }

  function resume(): void {
    clock.reset();
    commit({
      ...current.current,
      paused: false,
      feedback: '',
      loadNotice: '',
    });
  }

  return {
    session,
    newGame,
    restart,
    loadBoard,
    loadSnapshot,
    exportSnapshot,
    activate,
    resume,
    pauseClock: clock.synchronize,
    resumeClock: clock.reset,
  };
}
import { useEffect, useRef } from 'react';
import { isWon } from '../game.ts';
import { SelectionKind } from '../selection.ts';
import { CLOCK_INTERVAL_MS, createClock, elapsedStep } from './browser-clock.ts';
import { tickSession } from './session.ts';
import type { RefObject } from 'react';
import type { Session } from './session.ts';

export function useSessionClock(
  session: Session,
  current: RefObject<Session>,
  commit: (next: Session) => void,
  active = true,
) {
  const clock = useRef(createClock(performance.now()));
  const visible = useRef(!document.hidden);
  const activeRef = useRef(active);
  activeRef.current = active;
  const won = isWon(session.game);

  function running(): boolean {
    return (
      visible.current &&
      activeRef.current &&
      !current.current.paused &&
      current.current.game.started &&
      !isWon(current.current.game)
    );
  }

  function synchronize(generation = current.current.generation): void {
    if (generation !== current.current.generation) return;
    const now = performance.now();
    const step = elapsedStep(clock.current, now, running());
    clock.current = step.clock;
    if (step.milliseconds) commit(tickSession(current.current, generation, step.milliseconds));
  }

  useEffect(() => {
    const generation = session.generation;
    let active = true;
    let timer: number | undefined;
    function schedule(): void {
      window.clearTimeout(timer);
      if (!active || generation !== current.current.generation || !running()) return;
      const selection = current.current.game.selection;
      const delay =
        selection.kind === SelectionKind.mismatch
          ? Math.min(CLOCK_INTERVAL_MS, selection.remainingMs)
          : CLOCK_INTERVAL_MS;
      timer = window.setTimeout(() => {
        if (!active) return;
        synchronize(generation);
        schedule();
      }, delay);
    }
    function visibilityChanged(): void {
      if (!active || generation !== current.current.generation) return;
      synchronize(generation);
      visible.current = !document.hidden;
      schedule();
    }
    schedule();
    document.addEventListener('visibilitychange', visibilityChanged);
    return () => {
      active = false;
      window.clearTimeout(timer);
      document.removeEventListener('visibilitychange', visibilityChanged);
    };
  }, [active, session.generation, session.game.started, session.paused, won]);

  return {
    synchronize,
    reset: () => {
      clock.current = createClock(performance.now());
    },
  };
}

