  return game ? { ...game, elapsedMs } : null;
}

function isTournamentPhase(value: unknown): value is TournamentState['phase'] {
  return (
    value === 'ready' ||
    value === 'playing' ||
    value === 'between-turns' ||
    value === 'between-matches' ||
    value === 'finished'
  );
}

